const cleanString = (s: string) =>
  s
    ? s
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .replace(/[^a-z0-9]/g, "")
        .trim()
    : "";

const processTreatmentValue = (newVal: string): string => {
  const header = "Medicamentele se utilizeaza in ordinea prescrisa :";
  let processed = newVal;

  Object.entries(TREATMENT_SHORTCUTS).forEach(([key, shortcut]) => {
    const lastChar = processed.slice(-1);
    if (lastChar === " ") {
      const beforeLast = processed.slice(0, -1);
      if (
        beforeLast.endsWith(` ${key}`) ||
        beforeLast === key ||
        beforeLast.endsWith(`\n${key}`)
      ) {
        const base = beforeLast.slice(0, beforeLast.length - key.length);

        if (!base.includes(header)) {
          processed = header + "\n1. " + shortcut + " ";
        } else {
          let currentLines = base
            .split("\n")
            .map((l) => l.trim())
            .filter((l) => l !== "");
          let itemCount = 0;
          currentLines.forEach((l) => {
            if (/^\d+\./.test(l)) itemCount++;
          });
          processed =
            currentLines.join("\n") +
            `\n${itemCount + 1}. ` +
            shortcut +
            " ";
        }
      }
    }
  });
  return processed;
};

interface CustomDateItemRowProps {
  role: Role;
  customItem: CustomDateConfig;
  scheduledPatients: Appointment[];
  updateCustomDateSchedule: (
    doctorId: string,
    dateStr: string,
    startHour: number,
    endHour: number,
    intervalMinutes: number,
  ) => Promise<boolean>;
  removeActiveDate: (doctorId: string, dateStr: string) => Promise<boolean>;
  darkMode: boolean;
}

function CustomDateItemRow({
  role,
  customItem,
  scheduledPatients,
  updateCustomDateSchedule,
  removeActiveDate,
  darkMode,
}: CustomDateItemRowProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [startHour, setStartHour] = useState(customItem.startHour);
  const [endHour, setEndHour] = useState(customItem.endHour);
  const [intervalMinutes, setIntervalMinutes] = useState(customItem.intervalMinutes);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    setStartHour(customItem.startHour);
    setEndHour(customItem.endHour);
    setIntervalMinutes(customItem.intervalMinutes);
  }, [customItem.startHour, customItem.endHour, customItem.intervalMinutes]);

  const dateStr = customItem.date;
  const hasPatients = scheduledPatients.length > 0;
  let formattedDate = dateStr;
  try {
    formattedDate = format(parseISO(dateStr), "dd.MM.yyyy (EEE)", { locale: ro });
  } catch (e) {
    formattedDate = dateStr;
  }

  const handleSave = async () => {
    setIsSaving(true);
    const success = await updateCustomDateSchedule(
      role,
      dateStr,
      startHour,
      endHour,
      intervalMinutes,
    );
    setIsSaving(false);
    if (success) {
      setIsEditing(false);
    }
  };

  if (isEditing) {
    return (
      <div
        className={cn(
          "p-3 border rounded-xl text-xs font-bold transition-all shadow-sm space-y-2.5",
          darkMode
            ? "bg-slate-900 border-amber-500/60 text-slate-100"
            : "bg-amber-50/80 border-amber-300 text-slate-900",
        )}
      >
        <div className="flex items-center justify-between">
          <span className="font-black text-xs text-amber-700 dark:text-amber-400 flex items-center gap-1.5">
            <Pencil className="w-3.5 h-3.5" />
            Editează orar: {formattedDate}
          </span>
          <span className="text-[10px] text-slate-500 dark:text-slate-400 font-normal">
            Modifică orele sau intervalul
          </span>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
          <div>
            <label className="block text-[9px] font-black uppercase text-slate-500 mb-0.5">
              Ora Start
            </label>
            <input
              type="number"
              min={6}
              max={22}
              value={startHour}
              onChange={(e) => setStartHour(parseInt(e.target.value) || 0)}
              className={cn(
                "w-full text-xs p-1.5 border rounded-lg outline-none focus:ring-2 focus:ring-amber-500 font-semibold",
                darkMode ? "bg-slate-800 border-slate-700 text-slate-100" : "bg-white border-slate-300 text-slate-900",
              )}
            />
          </div>
          <div>
            <label className="block text-[9px] font-black uppercase text-slate-500 mb-0.5">
              Ora Sfârșit
            </label>
            <input
              type="number"
              min={7}
              max={23}
              value={endHour}
              onChange={(e) => setEndHour(parseInt(e.target.value) || 0)}
              className={cn(
                "w-full text-xs p-1.5 border rounded-lg outline-none focus:ring-2 focus:ring-amber-500 font-semibold",
                darkMode ? "bg-slate-800 border-slate-700 text-slate-100" : "bg-white border-slate-300 text-slate-900",
              )}
            />
          </div>
          <div>
            <label className="block text-[9px] font-black uppercase text-slate-500 mb-0.5">
              Interval (min)
            </label>
            <input
              type="number"
              min={5}
              max={120}
              value={intervalMinutes}
              onChange={(e) => setIntervalMinutes(parseInt(e.target.value) || 0)}
              className={cn(
                "w-full text-xs p-1.5 border rounded-lg outline-none focus:ring-2 focus:ring-amber-500 font-semibold",
                darkMode ? "bg-slate-800 border-slate-700 text-slate-100" : "bg-white border-slate-300 text-slate-900",
              )}
            />
          </div>
        </div>

        <div className="flex items-center justify-end gap-2 pt-1">
          <button
            type="button"
            onClick={() => {
              setStartHour(customItem.startHour);
              setEndHour(customItem.endHour);
              setIntervalMinutes(customItem.intervalMinutes);
              setIsEditing(false);
            }}
            className="px-2.5 py-1 text-xs font-bold rounded-lg border border-slate-300 dark:border-slate-700 text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 transition-all flex items-center gap-1"
          >
            <X className="w-3.5 h-3.5" />
            Anulează
          </button>
          <button
            type="button"
            disabled={isSaving}
            onClick={handleSave}
            className="px-3 py-1 text-xs font-black rounded-lg bg-emerald-600 text-white hover:bg-emerald-700 transition-all flex items-center gap-1 shadow-sm active:scale-95"
          >
            <Check className="w-3.5 h-3.5" />
            Salvează Modificările
          </button>
        </div>
      </div>
    );
  }

  return (
    <div
      className={cn(
        "flex items-center justify-between p-2.5 border rounded-xl text-xs font-bold transition-all shadow-sm gap-2",
        hasPatients
          ? "bg-emerald-50 text-emerald-900 border-emerald-300 dark:bg-emerald-950/40 dark:text-emerald-300 dark:border-emerald-800/80"
          : "bg-blue-50/80 text-blue-900 border-blue-200 dark:bg-blue-950/40 dark:text-blue-300 dark:border-blue-800/60",
      )}
    >
      <div className="flex items-center gap-2 flex-wrap">
        <span className="font-extrabold text-sm">{formattedDate}</span>
        <span className="text-[10px] px-2 py-0.5 rounded-md bg-white/80 dark:bg-slate-800/80 font-mono text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700">
          {customItem.startHour}:00 - {customItem.endHour}:00 ({customItem.intervalMinutes} min)
        </span>
        {hasPatients && (
          <span
            className="text-[9px] bg-emerald-600 text-white font-black px-2 py-0.5 rounded-md"
            title={`${scheduledPatients.length} pacienți programați în această zi`}
          >
            {scheduledPatients.length}{" "}
            {scheduledPatients.length === 1 ? "pacient" : "pacienți"}
          </span>
        )}
      </div>

      <div className="flex items-center gap-1.5 shrink-0">
        <button
          type="button"
          onClick={() => setIsEditing(true)}
          className="px-2.5 py-1.5 rounded-lg text-amber-700 dark:text-amber-400 bg-amber-50 dark:bg-amber-950/50 border border-amber-200 dark:border-amber-800/50 hover:bg-amber-100 dark:hover:bg-amber-900/60 transition-colors flex items-center gap-1 shadow-xs cursor-pointer active:scale-95"
          title="Editează orarul acestei zile"
        >
          <Pencil className="w-3.5 h-3.5" />
          <span className="text-[10px] font-bold">Editează</span>
        </button>

        <button
          type="button"
          onClick={() => removeActiveDate(role, dateStr)}
          className="px-2.5 py-1.5 rounded-lg text-rose-700 dark:text-rose-400 bg-rose-50 dark:bg-rose-950/50 border border-rose-200 dark:border-rose-800/50 hover:bg-rose-100 dark:hover:bg-rose-900/60 transition-colors flex items-center gap-1 shadow-xs cursor-pointer active:scale-95"
          title="Șterge această dată activată"
        >
          <Trash2 className="w-3.5 h-3.5" />
          <span className="text-[10px] font-bold">Șterge</span>
        </button>
      </div>
    </div>
  );
}

export const normalizePhone = (phone?: string | null): string => {
  if (!phone) return "";
  return phone.replace(/\D/g, "");
};

export const normalizePatientName = (name?: string | null): string => {
  if (!name) return "";
  return name
    .toLowerCase()
    .trim()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ");
};

export const findPatientMedicalRecord = (
  patientName: string | undefined | null,
  patientPhone: string | undefined | null,
  patientCnp: string | undefined | null,
  recordsList: MedicalRecord[],
): MedicalRecord | undefined => {
  if (!recordsList || recordsList.length === 0) return undefined;

  const cleanName = normalizePatientName(patientName);
  const cleanPhone = normalizePhone(patientPhone);
  const cleanCnp = (patientCnp || "").trim();

  // 1. Match by CNP if present
  if (cleanCnp) {
    const byCnp = recordsList.find((r) => r.patientCnp && r.patientCnp.trim() === cleanCnp);
    if (byCnp) return byCnp;
  }

  // 2. Exact name & phone match
  if (patientName && patientPhone) {
    const exact = recordsList.find(
      (r) =>
        r.patientName?.trim().toLowerCase() === patientName.trim().toLowerCase() &&
        r.patientPhone?.trim() === patientPhone.trim(),
    );
    if (exact) return exact;
  }

  // 3. Normalized name & normalized phone (digits only)
  if (cleanName && cleanPhone) {
    const byNorm = recordsList.find((r) => {
      const rName = normalizePatientName(r.patientName);
      const rPhone = normalizePhone(r.patientPhone);
      return rName === cleanName && rPhone === cleanPhone;
    });
    if (byNorm) return byNorm;
  }

  // 4. Normalized name match if phone matches partially or is empty on one side
  if (cleanName) {
    const byNameAndPartialPhone = recordsList.find((r) => {
      const rName = normalizePatientName(r.patientName);
      if (rName !== cleanName) return false;
      const rPhone = normalizePhone(r.patientPhone);
      if (!cleanPhone || !rPhone) return true;
      return (
        rPhone === cleanPhone ||
        rPhone.endsWith(cleanPhone) ||
        cleanPhone.endsWith(rPhone)
      );
    });
    if (byNameAndPartialPhone) return byNameAndPartialPhone;

    // 5. Sole name match
    const byNameOnly = recordsList.find((r) => normalizePatientName(r.patientName) === cleanName);
    if (byNameOnly) return byNameOnly;
  }

  // 6. Match by ID
  if (cleanName) {
    const expectedId = `${patientName || ""}_${patientPhone || ""}`.replace(/\s+/g, "_").toLowerCase();
    const byId = recordsList.find((r) => r.id === expectedId || r.id?.toLowerCase().includes(cleanName.replace(/\s+/g, "_")));
    if (byId) return byId;
  }

  return undefined;
};

const Clock = ({ darkMode }: { darkMode: boolean }) => {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => {
      setTime(new Date());
    }, 10000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div
      className={cn(
        "flex items-center gap-3 text-3xl sm:text-4xl font-medium font-mono",
        darkMode ? "text-blue-400" : "text-blue-600",
      )}
    >
      <ClockIcon className="w-8 h-8" />
      {format(time, "HH:mm")}
    </div>
  );
};

interface BufferedInputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'value' | 'onChange'> {
  value: string;
  onChange: (val: string) => void;
  processValue?: (val: string) => string;
  inputRef?: React.RefObject<HTMLInputElement | null>;
}

const BufferedInput: React.FC<BufferedInputProps> = ({
  value,
  onChange,
  processValue,
  inputRef,
  className,
  ...props
}) => {
  const [localValue, setLocalValue] = useState(value);
  const isFocused = useRef(false);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  useEffect(() => {
    if (!isFocused.current) {
      setLocalValue(value);
    }
  }, [value]);

  useEffect(() => {
    if (localValue === value) return;
    const timer = setTimeout(() => {
      onChangeRef.current(localValue);
    }, 350);
    return () => clearTimeout(timer);
  }, [localValue, value]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let val = e.target.value;
    if (processValue) {
      val = processValue(val);
    }
    setLocalValue(val);
  };

  const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
    isFocused.current = true;
    if (props.onFocus) {
      props.onFocus(e);
    }
  };

  const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
    isFocused.current = false;
    if (localValue !== value) {
      onChangeRef.current(localValue);
    }
    if (props.onBlur) {
      props.onBlur(e);
    }
  };

  return (
    <input
      {...props}
      ref={inputRef}
      value={localValue}
      onChange={handleChange}
      onFocus={handleFocus}
      onBlur={handleBlur}
      className={className}
    />
  );
};

