const BufferedBirthDateInput: React.FC<{
  value: string;
  onChange: (val: string) => void;
  inputRef?: React.RefObject<HTMLInputElement | null>;
  className?: string;
  onKeyDown?: (e: React.KeyboardEvent<HTMLInputElement>) => void;
  onBlur?: (e: React.FocusEvent<HTMLInputElement>) => void;
}> = ({ value, onChange, inputRef, className, onKeyDown, onBlur }) => {
  const toDisplay = (val: string) => {
    if (!val) return "";
    if (val.includes("-") && val.split("-")[0].length === 4) {
      return val.split("-").reverse().join("-");
    }
    return val;
  };

  const [localValue, setLocalValue] = useState(toDisplay(value));
  const isFocused = useRef(false);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  useEffect(() => {
    if (!isFocused.current) {
      setLocalValue(toDisplay(value));
    }
  }, [value]);

  const updateParent = (dispVal: string) => {
    let dbDate = dispVal;
    if (dispVal.length === 10) {
      const parts = dispVal.split("-");
      dbDate = `${parts[2]}-${parts[1]}-${parts[0]}`;
    }
    onChangeRef.current(dbDate);
  };

  useEffect(() => {
    const dbDate = localValue.length === 10 ? localValue.split("-").reverse().join("-") : localValue;
    if (dbDate === value) return;
    const timer = setTimeout(() => {
      updateParent(localValue);
    }, 350);
    return () => clearTimeout(timer);
  }, [localValue, value]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const inputVal = e.target.value;
    const cleanDigits = inputVal.replace(/\D/g, "");
    let formatted = "";
    if (cleanDigits.length <= 2) {
      formatted = cleanDigits;
    } else if (cleanDigits.length <= 4) {
      formatted = `${cleanDigits.slice(0, 2)}-${cleanDigits.slice(2, 4)}`;
    } else {
      formatted = `${cleanDigits.slice(0, 2)}-${cleanDigits.slice(2, 4)}-${cleanDigits.slice(4, 8)}`;
    }
    setLocalValue(formatted);
  };

  const handleFocus = () => {
    isFocused.current = true;
  };

  const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
    isFocused.current = false;
    updateParent(localValue);
    if (onBlur) {
      onBlur(e);
    }
  };

  return (
    <input
      ref={inputRef}
      type="text"
      maxLength={10}
      placeholder="ZZ-LL-AAAA"
      value={localValue}
      onChange={handleChange}
      onFocus={handleFocus}
      onBlur={handleBlur}
      onKeyDown={onKeyDown}
      className={className}
    />
  );
};

const BufferedPhoneInput: React.FC<{
  value: string;
  onChange: (val: string) => void;
  disabled?: boolean;
  className?: string;
  placeholder?: string;
  inputRef?: React.RefObject<HTMLInputElement | null>;
}> = ({ value, onChange, disabled, className, placeholder, inputRef }) => {
  const [localValue, setLocalValue] = useState(value);
  const isFocused = useRef(false);
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;

  useEffect(() => {
    if (!isFocused.current) {
      setLocalValue(value);
    }
  }, [value]);

  useEffect(() => {
    if (localValue === value) return;
    const timer = setTimeout(() => {
      onChangeRef.current(localValue);
    }, 350);
    return () => clearTimeout(timer);
  }, [localValue, value]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const rawDigits = e.target.value.replace(/\D/g, "");
    setLocalValue(rawDigits);
  };

  const handleFocus = () => {
    isFocused.current = true;
  };

  const handleBlur = () => {
    isFocused.current = false;
    if (localValue !== value) {
      onChangeRef.current(localValue);
    }
  };

  return (
    <input
      ref={inputRef}
      type="tel"
      disabled={disabled}
      value={disabled ? "" : formatPhoneNumber(localValue)}
      onChange={handleChange}
      onFocus={handleFocus}
      onBlur={handleBlur}
      className={className}
      placeholder={placeholder}
    />
  );
};

const NameSearchInput = ({
  initialValue,
  onSearch,
  onSync,
  darkMode,
}: {
  initialValue: string;
  onSearch: (val: string) => void;
  onSync: (val: string) => void;
  darkMode: boolean;
}) => {
  const [localVal, setLocalVal] = useState(initialValue);
  const onSyncRef = useRef(onSync);
  onSyncRef.current = onSync;

  useEffect(() => {
    setLocalVal(initialValue);
  }, [initialValue]);

  useEffect(() => {
    if (localVal === initialValue) return;
    const timer = setTimeout(() => {
      onSyncRef.current(localVal);
    }, 300);
    return () => clearTimeout(timer);
  }, [localVal, initialValue]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setLocalVal(e.target.value);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Enter") {
      onSearch(localVal);
    }
  };

  return (
    <input
      type="text"
      value={localVal}
      onChange={handleChange}
      onKeyDown={handleKeyDown}
      onBlur={() => onSync(localVal)}
      placeholder="Caută după nume..."
      className={cn(
        "pl-9 pr-3 py-1.5 border rounded-lg text-xs outline-none transition-all duration-300 w-36 focus:w-44 shadow-sm",
        darkMode
          ? "bg-slate-800 border-slate-700 text-slate-100 placeholder-slate-500 focus:border-blue-500 focus:ring-1 focus:ring-blue-500"
          : "bg-white border-slate-200 text-slate-900 placeholder-slate-450 focus:border-blue-500 focus:ring-1 focus:ring-blue-500",
      )}
    />
  );
};

