        (log.action || "").toLowerCase().includes(auditSearch.toLowerCase()) ||
        (log.details || "").toLowerCase().includes(auditSearch.toLowerCase());

      const matchesAction =
        auditActionFilter === "all" ||
        log.action === auditActionFilter;

      return matchesSearch && matchesAction;
