  const generateOrderNumber = (records: MedicalRecord[]) => {
    const now = new Date();
    const dateStr = format(now, "yyyyMMdd");

    const existingNumbers = new Set<string>();
    records.forEach((record) => {
      if (record.orderHistory) {
        record.orderHistory.forEach((order) => {
          if (order.orderNumber) {
            existingNumbers.add(order.orderNumber);
          }
        });
      }
      if (record.glassesOrder?.orderNumber) {
        existingNumbers.add(record.glassesOrder.orderNumber);
      }
    });

    let counter = 1;
    let newNumber = `${dateStr}-${counter.toString().padStart(2, "0")}`;

    while (existingNumbers.has(newNumber)) {
      counter++;
      newNumber = `${dateStr}-${counter.toString().padStart(2, "0")}`;
    }

    return newNumber;
  };
