  const deduplicateUsers = (rawUsers: any[]) => {
    const canonicalOrder: Record<string, number> = {
      admin: 1,
      turcanu: 2,
      zorila: 3,
      ilie: 4,
      receptie: 5,
      tv: 6,
    };

    const sorted = [...rawUsers].sort((a, b) => {
      const rankA = canonicalOrder[a.id] ?? 100;
      const rankB = canonicalOrder[b.id] ?? 100;
      if (rankA !== rankB) return rankA - rankB;

      const orderA = a.order ?? 999;
      const orderB = b.order ?? 999;
      if (orderA !== orderB) return orderA - orderB;

      return (a.id || "").localeCompare(b.id || "");
    });

    const seenIds = new Set<string>();
    const seenRoles = new Set<string>();
    const seenNamesAndRoles = new Set<string>();

    const result: any[] = [];

    for (const user of sorted) {
      if (!user || !user.id) continue;

      if (seenIds.has(user.id)) continue;

      if (user.role === "tv" || user.role === "admin") {
        if (seenRoles.has(user.role)) continue;
        seenRoles.add(user.role);
      }

      const nameStr = (user.name || "").trim().toLowerCase();
      const roleStr = (user.role || "").trim().toLowerCase();
      const nameRoleKey = `${nameStr}_${roleStr}`;

      if (
        user.role === "tv" ||
        user.role === "admin" ||
        user.role === "frontdesk" ||
        nameStr.includes("turcanu") ||
        nameStr.includes("trucanu")
      ) {
        if (seenNamesAndRoles.has(nameRoleKey)) continue;
        seenNamesAndRoles.add(nameRoleKey);
      }

      seenIds.add(user.id);
      result.push(user);
    }

    return result;
  };

