  useEffect(() => {
    if (!profile) return; // Only if signed in
    if (profile.role === "tv") {
      if (showScreenSaver) {
        setShowScreenSaver(false);
      }
      return; // Disable screensaver for TV user
    }
    if (showScreenSaver) return; // If screensaver is already showing, do nothing

    const timeoutMinutes = Math.max(1, clinicConfig?.inactivityTimeoutMinutes ?? 5);
    const timeoutMs = timeoutMinutes * 60 * 1000;

    let idleTimer: any;

    const resetTimer = () => {
      if (idleTimer) clearTimeout(idleTimer);
      idleTimer = setTimeout(() => {
        setShowScreenSaver(true);
      }, timeoutMs);
    };

    const activityEvents = [
      "mousemove",
      "keydown",
      "mousedown",
      "scroll",
      "touchstart",
    ];

    activityEvents.forEach((event) => {
      window.addEventListener(event, resetTimer);
    });

    resetTimer();

    return () => {
      if (idleTimer) clearTimeout(idleTimer);
      activityEvents.forEach((event) => {
        window.removeEventListener(event, resetTimer);
      });
    };
  }, [profile, showScreenSaver, clinicConfig?.inactivityTimeoutMinutes]);

