  const currentPatientAppointment = useMemo(() => {
    if (!currentMedicalRecord) return null;

    const recName = cleanString(currentMedicalRecord.patientName || "");
    const recPhone = cleanString(currentMedicalRecord.patientPhone || "");

    if (activeAppointment) {
      const activeName = cleanString(activeAppointment.patientName || "");
      const activePhone = cleanString(activeAppointment.patientPhone || "");
      if (recName && activeName && recName === activeName) {
        const foundInState = appointments.find(
          (a) => a.id === activeAppointment.id
        );
        return foundInState || activeAppointment;
      }
    }

    if (!recName) return null;

    const matching = appointments.filter((a) => {
      const aName = cleanString(a.patientName || "");
      const aPhone = cleanString(a.patientPhone || "");
      const nameMatch =
        recName &&
        aName &&
        (recName === aName || aName.includes(recName) || recName.includes(aName));
      if (!nameMatch) return false;
      const phoneMatch = recPhone && aPhone ? recPhone === aPhone : true;
      return nameMatch && phoneMatch;
    });

    if (matching.length === 0) return null;

    const todayApp = matching.find(
      (a) => a.startTime && isSameDay(parseISO(a.startTime), new Date())
    );
    if (todayApp) return todayApp;

    matching.sort(
      (a, b) =>
        new Date(b.startTime).getTime() - new Date(a.startTime).getTime()
    );
    return matching[0];
  }, [currentMedicalRecord, activeAppointment, appointments]);
