  const handleBooking = async () => {
    if (!selectedSlot) {
      setBookingError("Eroare: Nu a fost selectat niciun interval orar!");
      return;
    }
    if (!patientName || !patientName.trim()) {
      setBookingError("Numele pacientului este obligatoriu!");
      return;
    }
    if (!patientBirthDate || !patientBirthDate.trim()) {
      setBookingError("Data nașterii este obligatorie pentru a putea efectua programarea!");
      return;
    }
    if (!faraTelefon && (!patientPhone || !patientPhone.trim())) {
      setBookingError("Numărul de telefon este obligatoriu! Completați-l sau selectați opțiunea 'Fără telefon'.");
      return;
    }
    if (!canAddAppointments) return;

    setLoading(true);
    const config = getDoctorConfig(selectedSlot.doctorId);
    const dayConfig = config.dayConfigs[getDay(selectedSlot.time)];
    const endTime = addMinutes(selectedSlot.time, dayConfig.intervalMinutes);

    const calculatedAge =
      calculateAge(patientBirthDate, selectedSlot.time) || 0;

    if (calculatedAge > 110) {
      setBookingError("Vârsta nu poate fi mai mare de 110 ani!");
      setLoading(false);
      return;
    }

    const birthDateObj = new Date(patientBirthDate);
    const today = new Date();
    const todayEnd = new Date(
      today.getFullYear(),
      today.getMonth(),
      today.getDate(),
      23,
      59,
      59,
      999,
    );
    if (birthDateObj > todayEnd) {
      setBookingError("Data nașterii nu poate fi mai mare decât ziua curentă!");
      setLoading(false);
      return;
    }

    if (!faraTelefon && !isValidPhone(patientPhone)) {
      setBookingError(
        "Numărul de telefon care începe cu 07 sau 0248 trebuie să aibă exact 10 cifre!",
      );
      setLoading(false);
      return;
    }

    const valPhone = faraTelefon ? "" : patientPhone;

    setBookingError(null);
    try {
      if (reschedulingAppointment) {
        const oldId = reschedulingAppointment.id;
        const appData = {
          patientName,
          patientAge: calculatedAge,
          patientBirthDate,
          patientPhone: valPhone,
          patientSex,
          patientNotes,
          patientSymptomSelect: symptomSelect,
          patientSymptomText: symptomText,
          doctorId: selectedSlot.doctorId,
          startTime: selectedSlot.time.toISOString(),
          endTime: endTime.toISOString(),
          status: "scheduled" as const,
          isControl: rescheduleAsControl,
          createdAt: new Date().toISOString(),
        };
        await addDoc(collection(db, "appointments"), removeUndefined(appData));
        await deleteDoc(doc(db, "appointments", oldId));
        setReschedulingAppointment(null);
        setRescheduleAsControl(false);

        await syncMedicalRecord(
          patientName,
          valPhone,
          calculatedAge,
          patientBirthDate,
          patientSex,
          reschedulingAppointment?.patientName,
          reschedulingAppointment?.patientPhone,
        );
      } else if (editingAppointment) {
        await updateDoc(
          doc(db, "appointments", editingAppointment.id),
          removeUndefined({
            patientName,
            patientAge: calculatedAge,
            patientBirthDate,
            patientPhone: valPhone,
            patientSex,
            patientNotes,
            patientSymptomSelect: symptomSelect,
            patientSymptomText: symptomText,
            doctorId: selectedSlot.doctorId,
            startTime: selectedSlot.time.toISOString(),
            endTime: endTime.toISOString(),
          }),
        );
        await syncMedicalRecord(
          patientName,
          valPhone,
          calculatedAge,
          patientBirthDate,
          patientSex,
          editingAppointment?.patientName,
          editingAppointment?.patientPhone,
        );
      } else {
        await addDoc(
          collection(db, "appointments"),
          removeUndefined({
            patientName,
            patientAge: calculatedAge,
            patientBirthDate,
            patientPhone: valPhone,
            patientSex,
            patientNotes,
            patientSymptomSelect: symptomSelect,
            patientSymptomText: symptomText,
            doctorId: selectedSlot.doctorId,
            startTime: selectedSlot.time.toISOString(),
            endTime: endTime.toISOString(),
            status: "scheduled",
          }),
        );
      }
      setIsBookingModalOpen(false);
      setEditingAppointment(null);
      setReschedulingAppointment(null); // Clear rescheduling mode
      setPatientName("");
      setPatientAge("");
      setPatientBirthDate("");
      setPatientPhone("");
      setFaraTelefon(true);
      setHasStoredPhone(false);
      setPatientSex("");
      setPatientNotes("");
      setSymptomSelect("");
      setSymptomText("");
    } catch (error) {
      console.error("Error booking/updating appointment:", error);
      const errInfo = {
        error: error instanceof Error ? error.message : String(error),
        authInfo: {
          userId: auth.currentUser?.uid,
          email: auth.currentUser?.email,
          emailVerified: auth.currentUser?.emailVerified,
          isAnonymous: auth.currentUser?.isAnonymous,
        },
        operationType: editingAppointment ? "update" : "create",
        path: "appointments",
      };
      console.error("Firestore Error: ", JSON.stringify(errInfo));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const rescheduleId = params.get("rescheduleId");
    if (rescheduleId && appointments.length > 0) {
      const app = appointments.find((a) => a.id === rescheduleId);
      if (app) {
        setReschedulingAppointment(app);
        window.history.replaceState({}, "", window.location.pathname);
      }
    }
  }, [appointments]);

  const exportToPDF = (type: "day" | "week") => {
    const doc = new jsPDF();

    const doctorFilter = profile?.role.startsWith("doctor")
      ? profile.role
      : selectedDoctorForExport;

    const title =
      type === "day"
        ? `Programări - ${format(selectedDate, "dd  MMMM  yyyy", { locale: ro })}`
        : `Programări Săptămânale - ${format(startOfWeek(selectedDate, { weekStartsOn: 1 }), "dd.MM")} - ${format(endOfWeek(selectedDate, { weekStartsOn: 1 }), "dd.MM.yyyy")}`;

    doc.setFontSize(16);
    doc.text(normalizeForPDF(title), 14, 22);

    if (doctorFilter !== "all") {
      doc.setFontSize(13);
      const doctorLabel = doctorFilter === "admin" ? "Ing. Optometrist" : getRoleLabel(doctorFilter as Role);
      doc.text(normalizeForPDF(`Medic/Optometrist: ${doctorLabel}`), 14, 30);
    }

    doc.setFontSize(11);
    doc.setTextColor(100);
    doc.text(
      `Generat la: ${format(new Date(), "dd.MM.yyyy HH:mm")}`,
      14,
      doctorFilter !== "all" ? 38 : 30,
    );

    const filteredApps = appointments
      .filter((app) => {
        const appDate = parseISO(app.startTime);
        const isDoctorMatch =
          doctorFilter === "all" || app.doctorId === doctorFilter;

        if (!isDoctorMatch) return false;

        if (type === "day") {
          return isSameDay(appDate, selectedDate);
        } else {
          const start = startOfWeek(selectedDate, { weekStartsOn: 1 });
          const end = endOfWeek(selectedDate, { weekStartsOn: 1 });
          return isWithinInterval(appDate, { start, end });
        }
      })
      .sort((a, b) => a.startTime.localeCompare(b.startTime));

    const tableData = filteredApps.map((app) => [
      format(parseISO(app.startTime), "dd.MM HH:mm"),
      app.patientName,
      app.patientPhone,
      app.doctorId === "admin" ? "Ing. Optometrist" : (getRoleLabel(app.doctorId as Role) || app.doctorId),
      app.patientNotes || "-",
    ]);

    autoTable(doc, {
      startY: doctorFilter !== "all" ? 45 : 40,
      head: [["Data/Ora", "Pacient", "Telefon", "Medic/Optometrist", "Note"]],
      body: tableData,
      theme: "grid",
      headStyles: { fillColor: [37, 99, 235] },
      styles: { fontSize: 9 },
      columnStyles: {
        0: { cellWidth: 30 },
        1: { cellWidth: 35 },
        2: { cellWidth: 30 },
        3: { cellWidth: 35 },
        4: { cellWidth: "auto" },
      },
    });

    const finalY = (doc as any).lastAutoTable.finalY || 150;
    doc.setFontSize(14);
    doc.setTextColor(0);
    doc.text(normalizeForPDF("Sumar Programări:"), 14, finalY + 15);

    doc.setFontSize(11);
    if (type === "week") {
      const start = startOfWeek(selectedDate, { weekStartsOn: 1 });
      const weekDays = Array.from({ length: 6 }, (_, i) => addDays(start, i)); // Mon-Sat

      weekDays.forEach((day, idx) => {
        const count = filteredApps.filter((app) =>
          isSameDay(parseISO(app.startTime), day),
        ).length;
        doc.text(
          normalizeForPDF(
            `${format(day, "EEEE, dd.MM", { locale: ro })}: ${count} pacienți`,
          ),
          14,
          finalY + 25 + idx * 7,
        );
      });

      doc.setFontSize(12);
      doc.setFont("helvetica", "bold");
      doc.text(
        normalizeForPDF(`Total Săptămână: ${filteredApps.length} pacienți`),
        14,
        finalY + 25 + 6 * 7 + 5,
      );
    } else {
      doc.text(
        normalizeForPDF(`Total Zi: ${filteredApps.length} pacienți`),
        14,
        finalY + 25,
      );
    }

    doc.save(`programari_${type}_${format(selectedDate, "yyyy-MM-dd")}.pdf`);
    setIsExportModalOpen(false);
  };

  const startRescheduling = (app: Appointment) => {
    if (!canDeleteOrReschedule) return;
    setReschedulingAppointment(app);
    setRescheduleAsControl(false);
    setIsRescheduleInfoModalOpen(true);
  };

  const confirmDeleteDirectly = (id: string) => {
    if (!canDeleteOrReschedule) return;
    const app = appointments.find((a) => a.id === id);
    if (app) {
      setAppointmentToCancel(app);
      setIsDeleteConfirmModalOpen(true);
    }
  };

  const cancelAppointment = async (id: string) => {
    if (!canDeleteOrReschedule) return;
    const app = appointments.find((a) => a.id === id);
    if (app) {
      setAppointmentToCancel(app);
      setIsCancelOptionsModalOpen(true);
    }
  };

  const confirmDeleteAppointment = async () => {
    if (!appointmentToCancel) return;
    setDeletedAppointments((prev) => [...prev, appointmentToCancel].slice(-20));
    await deleteDoc(doc(db, "appointments", appointmentToCancel.id));
    setIsCancelOptionsModalOpen(false);
    setIsDeleteConfirmModalOpen(false);
    setAppointmentToCancel(null);
    setIsBookingModalOpen(false);
    setIsMedicalRecordModalOpen(false);
    setIsRescheduleInfoModalOpen(false);
    setReschedulingAppointment(null);
  };

  const handleDeletePatientDefinitively = async (app: Appointment) => {
    try {
      setLoading(true);

      const targetName = (app.patientName || "").trim();
      const targetPhone = (app.patientPhone || "").trim();

      const cleanString = (s?: string) =>
        s
          ? s
              .normalize("NFD")
              .replace(/[\u0300-\u036f]/g, "")
              .toLowerCase()
              .replace(/[^a-z0-9]/g, "")
              .trim()
          : "";

      const targetNameClean = cleanString(targetName);
      const targetPhoneClean = targetPhone.replace(/\D/g, "");

      if (!targetNameClean) {
        setErrorMessage("Numele pacientului este invalid sau lipsă.");
        return;
      }

      let batch = writeBatch(db);
      let count = 0;

      const commitBatchIfNeeded = async () => {
        if (count >= 400) {
          await batch.commit();
          batch = writeBatch(db);
          count = 0;
        }
      };

      const recordIdsToDelete = new Set<string>();

      const isPatientMatch = (data: {
        id?: string;
        patientName?: string;
        patientPhone?: string;
        patientId?: string;
      }) => {
        if (!data) return false;

        if (app.id && data.id === app.id) return true;
        if (data.id && recordIdsToDelete.has(data.id)) return true;
        if (data.patientId && recordIdsToDelete.has(data.patientId)) return true;

        const dNameClean = cleanString(data.patientName || "");
        const dPhoneClean = (data.patientPhone || "").replace(/\D/g, "");

        if (!dNameClean || dNameClean !== targetNameClean) return false;

        if (targetPhoneClean !== "" && dPhoneClean !== "") {
          return targetPhoneClean === dPhoneClean;
        }

        if (targetPhoneClean === "" && dPhoneClean !== "") {
          return false;
        }

        return true;
      };

      // 1. Fetch ALL medicalRecords from Firestore to ensure complete deletion
      const snapMedicalRecords = await getDocs(collection(db, "medicalRecords"));
      for (const d of snapMedicalRecords.docs) {
        const data = d.data();
        if (isPatientMatch({ id: d.id, ...data })) {
          recordIdsToDelete.add(d.id);
          batch.delete(d.ref);
          count++;
          await commitBatchIfNeeded();
        }
      }

      // Also explicitly delete formula document ID keys if target phone exists
      if (targetPhoneClean) {
        const formulaId1 = `${targetName.toLowerCase().trim()}_${targetPhone.trim()}`;
        const formulaId2 = `${targetName}_${targetPhone}`.replace(/\s+/g, "_").toLowerCase();
        recordIdsToDelete.add(formulaId1);
        recordIdsToDelete.add(formulaId2);
        batch.delete(doc(db, "medicalRecords", formulaId1));
        count++;
        await commitBatchIfNeeded();
        batch.delete(doc(db, "medicalRecords", formulaId2));
        count++;
        await commitBatchIfNeeded();
      }

      // 2. Fetch ALL appointments from Firestore
      const snapAppointments = await getDocs(collection(db, "appointments"));
      for (const d of snapAppointments.docs) {
        const data = d.data();
        if (isPatientMatch({ id: d.id, ...data })) {
          batch.delete(d.ref);
          count++;
          await commitBatchIfNeeded();
        }
      }

      // 3. Fetch ALL glasses_orders from Firestore
      const snapOrders = await getDocs(collection(db, "glasses_orders"));
      for (const d of snapOrders.docs) {
        const data = d.data();
        if (isPatientMatch({ id: d.id, ...data })) {
          batch.delete(d.ref);
          count++;
          await commitBatchIfNeeded();
        }
      }

      // 4. Fetch ALL medicalDocuments from Firestore
      const snapDocs = await getDocs(collection(db, "medicalDocuments"));
      for (const d of snapDocs.docs) {
        const data = d.data();
        if (isPatientMatch({ id: d.id, ...data })) {
          batch.delete(d.ref);
          count++;
          await commitBatchIfNeeded();
        }
      }

      // 5. Fetch ALL reception_alerts from Firestore
      const snapAlerts = await getDocs(collection(db, "reception_alerts"));
      for (const d of snapAlerts.docs) {
        const data = d.data();
        if (
          isPatientMatch({ id: d.id, ...data }) ||
          Array.from(recordIdsToDelete).some((id) => d.id.startsWith(`${id}_`))
        ) {
          batch.delete(d.ref);
          count++;
          await commitBatchIfNeeded();
        }
      }

      if (count > 0) {
        await batch.commit();
      }

      // 6. Purge from local backups and localStorage
      setDeletedAppointments((prev) => prev.filter((item) => !isPatientMatch(item)));
      setDeletedPatientsBackup((prev) => prev.filter((item) => !isPatientMatch(item.data || item)));
      setDeletedAppointmentsBackup((prev) => prev.filter((item) => !isPatientMatch(item.data || item)));

      try {
        const savedPatients = localStorage.getItem("deletedPatientsBackup");
        if (savedPatients) {
          const parsed = JSON.parse(savedPatients);
          if (Array.isArray(parsed)) {
            const updated = parsed.filter((item) => !isPatientMatch(item.data || item));
            localStorage.setItem("deletedPatientsBackup", JSON.stringify(updated));
          }
        }
        const savedApps = localStorage.getItem("deletedAppointmentsBackup");
        if (savedApps) {
          const parsed = JSON.parse(savedApps);
          if (Array.isArray(parsed)) {
            const updated = parsed.filter((item) => !isPatientMatch(item.data || item));
            localStorage.setItem("deletedAppointmentsBackup", JSON.stringify(updated));
          }
        }
      } catch (e) {
        console.error("Error updating localStorage backups on permanent delete", e);
      }

      // 7. Instantly purge from active React state
      setMedicalRecords((prev) => prev.filter((item) => !isPatientMatch(item)));
      setAppointments((prev) => prev.filter((item) => !isPatientMatch(item)));
      setMedicalDocuments((prev) => prev.filter((item) => !isPatientMatch(item)));
      setReceptionAlerts((prev) => prev.filter((item) => !isPatientMatch(item)));
      setSearchResults((prev) => prev.filter((item) => !isPatientMatch(item)));

      if (currentMedicalRecord && isPatientMatch(currentMedicalRecord)) {
        setCurrentMedicalRecord(null);
        setIsMedicalRecordModalOpen(false);
      }

      await logActivity(
        "Ștergere Definitivă Pacient",
        `Pacientul ${targetName} (${targetPhone}) a fost șters definitiv din clinică. ` +
        `Toate fișele, programările, rețetele, ochelarii, documentele și alertele au fost eliminate.`
      );

      setSuccessMessage(`Pacientul ${targetName} a fost șters definitiv din sistem.`);
      setIsDeletePatientDefinitivelyModalOpen(false);
      setPatientToDeleteDefinitively(null);
    } catch (err: any) {
      console.error("Error deleting patient definitively:", err);
      setErrorMessage("Eroare la ștergerea definitivă: " + (err.message || String(err)));
    } finally {
      setLoading(false);
    }
  };

  const undoLastDelete = async () => {
    if (deletedAppointments.length === 0) return;
    const lastDeleted = deletedAppointments[deletedAppointments.length - 1];
    try {
      setLoading(true);
      await setDoc(
        doc(db, "appointments", lastDeleted.id),
        removeUndefined(lastDeleted),
      );
      setDeletedAppointments((prev) => prev.slice(0, -1));
      setSuccessMessage(
        `Pacientul ${lastDeleted.patientName} a fost restaurat cu succes în calendar!`,
      );
    } catch (err) {
      console.error("Error restoring appointment:", err);
      setErrorMessage("Eroare la restaurarea pacientului.");
    } finally {
      setLoading(false);
    }
  };

  const rescheduleAppointment = () => {
    if (!appointmentToCancel) return;
    setReschedulingAppointment(appointmentToCancel);
    setIsCancelOptionsModalOpen(false);
    setIsBookingModalOpen(false);
    setIsMedicalRecordModalOpen(false);
    setIsSearchModalOpen(false);
    setAppointmentToCancel(null);
  };

