    doc.setFont("helvetica", "normal");
    doc.line(16, y + 1.5, 30, y + 1.5);

    doc.text(`bl.`, 32, y);
    doc.setFont("helvetica", "bold");
    doc.text(documentForm.patientBloc || "", 38, y);
    doc.setFont("helvetica", "normal");
