    doc.text(`ap.`, 52, y);
    doc.setFont("helvetica", "bold");
    doc.text(documentForm.patientApartament || "", 58, y);
    doc.setFont("helvetica", "normal");
    doc.line(57, y + 1.5, 70, y + 1.5);

    doc.text(`sect. ....; avand ocupatia de:`, 72, y);
