  const updateDayConfig = async (
    doctorId: string,
    dayIdx: number,
    dayUpdates: Partial<DayConfig>,
  ) => {
    if (
      dayUpdates.intervalMinutes !== undefined &&
      dayUpdates.intervalMinutes <= 0
    ) {
      setErrorMessage("Intervalul trebuie să fie mai mare de 0 minute.");
      return;
    }

    const config = getDoctorConfig(doctorId);

    const newDayConfigs = { ...config.dayConfigs };
    const updatedDayConfig = { ...newDayConfigs[dayIdx], ...dayUpdates };

    newDayConfigs[dayIdx] = updatedDayConfig;
    await updateConfig(doctorId, { dayConfigs: newDayConfigs });
  };

  const toggleBlockedDate = async (doctorId: string, dateStr: string, forceImmediate = false) => {
    const config = getDoctorConfig(doctorId);
    const currentBlocked = config.blockedDates || [];
    const isCurrentlyBlocked = currentBlocked.includes(dateStr);
    const newBlocked = isCurrentlyBlocked
      ? currentBlocked.filter((d) => d !== dateStr)
      : [...currentBlocked, dateStr];

    if (isConfigModalOpen) {
      setTempConfigs((prev) =>
        prev.map((c) =>
          c.doctorId === doctorId || c.id === doctorId
            ? { ...c, blockedDates: newBlocked, id: doctorId, doctorId }
            : c,
        ),
      );
    }

    await updateConfig(
      doctorId,
      { blockedDates: newBlocked },
      forceImmediate || !isConfigModalOpen,
    );

    try {
      const formatted = format(parseISO(dateStr), "dd.MM.yyyy");
      setSuccessMessage(
        isCurrentlyBlocked
          ? `Data ${formatted} a fost deblocată cu succes!`
          : `Data ${formatted} a fost marcată ca absență (blocată)!`,
      );
    } catch {
      setSuccessMessage(
        isCurrentlyBlocked
          ? `Data ${dateStr} a fost deblocată cu succes!`
          : `Data ${dateStr} a fost marcată ca absență (blocată)!`,
      );
    }
  };

  const toggleActiveSaturday = async (doctorId: string, dateStr: string) => {
    const config = getDoctorConfig(doctorId);
    const currentActive = config.activeSaturdays || [];

    const otherDoctors = DOCTOR_ROLES.filter((r) => r !== doctorId);
    const isAlreadyClaimed = otherDoctors.some((role) =>
      getDoctorConfig(role).activeSaturdays?.includes(dateStr),
    );

    if (isAlreadyClaimed && !currentActive.includes(dateStr)) {
      alert("Această sâmbătă este deja rezervată de un alt medic!");
      return;
    }

    const newActive = currentActive.includes(dateStr)
      ? currentActive.filter((d) => d !== dateStr)
      : [...currentActive, dateStr];

    if (isConfigModalOpen) {
      setTempConfigs((prev) =>
        prev.map((c) =>
          c.doctorId === doctorId || c.id === doctorId
            ? { ...c, activeSaturdays: newActive, id: doctorId, doctorId }
            : c,
        ),
      );
    }

    await updateConfig(doctorId, { activeSaturdays: newActive });
  };

  const activateSpecificDate = async (
    doctorId: string,
    dateStr: string,
    startHour: number,
    endHour: number,
    intervalMinutes: number,
  ) => {
    if (!dateStr) return;
    if (startHour >= endHour) {
      alert("Ora de început trebuie să fie mai mică decât ora de sfârșit!");
      return;
    }
    if (intervalMinutes <= 0) {
      alert("Intervalul orar trebuie să fie mai mare de 0 minute!");
      return;
    }

    const config = getDoctorConfig(doctorId);
    const currentCustom = config.customActiveDates || [];

    // 1. Uniqueness check for this doctor
    if (currentCustom.some((c) => c.date === dateStr)) {
      alert(
        `Data ${format(parseISO(dateStr), "dd.MM.yyyy")} este deja activată pentru acest medic!`,
      );
      return;
    }

    // 2. Conflict check across other doctors
    const otherDoctors = DOCTOR_ROLES.filter((r) => r !== doctorId);
    const claimedRole = otherDoctors.find((role) => {
      const cfg = getDoctorConfig(role);
      return (
        cfg.customActiveDates?.some((c) => c.date === dateStr) ||
        cfg.activeSaturdays?.includes(dateStr)
      );
    });

    if (claimedRole) {
      alert(
        `Această dată (${format(parseISO(dateStr), "dd.MM.yyyy")}) este deja rezervată de alt medic (${getDoctorName(
          claimedRole,
        )}).`,
      );
      return;
    }

    const newCustom = [
      ...currentCustom,
      { date: dateStr, startHour, endHour, intervalMinutes },
    ].sort((a, b) => a.date.localeCompare(b.date));

    await updateConfig(doctorId, { customActiveDates: newCustom }, true);
    setSuccessMessage(
      `Data unică ${format(parseISO(dateStr), "dd.MM.yyyy")} (${startHour}:00 - ${endHour}:00, ${intervalMinutes} min) a fost activată cu succes!`,
    );
  };

  const removeActiveDate = async (doctorId: string, dateStr: string, skipConfirm = false) => {
    const config = getDoctorConfig(doctorId);
    const currentCustom = config.customActiveDates || [];
    const currentActiveSaturdays = config.activeSaturdays || [];

    // Check if doctor has scheduled patients on this date
    const scheduledPatients = appointments.filter(
      (a) =>
        a.doctorId === doctorId &&
        a.startTime?.startsWith(dateStr) &&
        a.status !== "cancelled",
    );

    if (scheduledPatients.length > 0 && !skipConfirm) {
      const confirmed = confirm(
        `Data ${format(
          parseISO(dateStr),
          "dd.MM.yyyy",
        )} are ${scheduledPatients.length} pacient(ți) programați.\n\nSigur doriți să o eliminați din lista de date unice active? Pacienții vor RĂMÂNE salvați în calendar.`,
      );
      if (!confirmed) return false;
    }

    const newCustom = currentCustom.filter((c) => c.date !== dateStr);
    const newActiveSat = currentActiveSaturdays.filter((d) => d !== dateStr);

    await updateConfig(
      doctorId,
      {
        customActiveDates: newCustom,
        activeSaturdays: newActiveSat,
      },
      true,
    );
    setSuccessMessage(
      `Data ${format(
        parseISO(dateStr),
        "dd.MM.yyyy",
      )} a fost eliminată din lista din setări. Programările pacienților rămân intacte în calendar.`,
    );
    return true;
  };

  const updateCustomDateSchedule = async (
    doctorId: string,
    dateStr: string,
    startHour: number,
    endHour: number,
    intervalMinutes: number,
  ) => {
    if (startHour >= endHour) {
      alert("Ora de început trebuie să fie mai mică decât ora de sfârșit!");
      return false;
    }
    if (intervalMinutes <= 0) {
      alert("Intervalul orar trebuie să fie mai mare de 0 minute!");
      return false;
    }

    const config = getDoctorConfig(doctorId);
    const currentCustom = config.customActiveDates || [];

    const newCustom = currentCustom.map((item) => {
      if (item.date === dateStr) {
        return { date: dateStr, startHour, endHour, intervalMinutes };
      }
      return item;
    });

    await updateConfig(doctorId, { customActiveDates: newCustom }, true);
    setSuccessMessage(
      `Orarul pentru data ${format(
        parseISO(dateStr),
        "dd.MM.yyyy",
      )} a fost actualizat (${startHour}:00 - ${endHour}:00, ${intervalMinutes} min)!`,
    );
    return true;
  };

