  const compressAndResizeImage = (
    file: File,
    maxBytes: number = 800000,
    maxDim: number = 800,
  ): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement("canvas");
          let width = img.width;
          let height = img.height;

          const MAX_DIM = maxDim;
          if (width > MAX_DIM || height > MAX_DIM) {
            if (width > height) {
              height = Math.round((height * MAX_DIM) / width);
              width = MAX_DIM;
            } else {
              width = Math.round((width * MAX_DIM) / height);
              height = MAX_DIM;
            }
          }

          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext("2d");
          if (!ctx) {
            resolve(event.target?.result as string);
            return;
          }

          ctx.drawImage(img, 0, 0, width, height);

          let quality = 0.8;
          let dataUrl = canvas.toDataURL("image/jpeg", quality);

          while (dataUrl.length * 0.75 > maxBytes && quality > 0.1) {
            quality -= 0.1;
            dataUrl = canvas.toDataURL("image/jpeg", quality);
          }

          resolve(dataUrl);
        };
        img.onerror = (err) => reject(err);
        img.src = event.target?.result as string;
      };
      reader.onerror = (err) => reject(err);
      reader.readAsDataURL(file);
    });
  };

  const handleLogoUpload = async (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 8388608) {
      alert("Imaginea este prea mare. Vă rugăm alegeți o imagine sub 8MB.");
      return;
    }

    try {
      setLoading(true);
      const compressedBase64 = await compressAndResizeImage(file, 800000);
      await updateClinicConfig({ logoUrl: compressedBase64 });
    } catch (err: any) {
      console.error("Error processing logo upload:", err);
      alert("A apărut o eroare la prelucrarea și optimizarea imaginii.");
    } finally {
      setLoading(false);
    }
  };

