  const handleExportData = () => {
    const backupData = {
      appointments,
      medicalRecords,
      availableUsers,
      configs,
      clinicConfig,
      timestamp: new Date().toISOString(),
      version: "1.0",
      app: "ClinicManager",
    };

    const blob = new Blob([JSON.stringify(backupData, null, 2)], {
      type: "application/json",
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `backup_clinica_${format(new Date(), "yyyy-MM-dd_HH-mm")}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleImportData = (e: ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);

        if (!json.appointments || !json.medicalRecords) {
          throw new Error(
            "Formatul fișierului este invalid sau lipsesc date esențiale.",
          );
        }

        if (
          window.confirm(
            "ATENȚIE: Sunteți sigur că doriți să importați aceste date? Această acțiune va încerca să suprascrie datele actuale din baza de date.",
          )
        ) {
          setLoading(true);
          try {
            setAppointments(json.appointments);
            setMedicalRecords(json.medicalRecords);
            if (json.availableUsers) setAvailableUsers(json.availableUsers);
            if (json.configs) setConfigs(json.configs);
            if (json.clinicConfig) setClinicConfig(json.clinicConfig);

            for (const app of json.appointments) {
              await setDoc(
                doc(db, "appointments", app.id),
                removeUndefined(app),
              );
            }
            for (const rec of json.medicalRecords) {
              await setDoc(
                doc(db, "medicalRecords", rec.id),
                removeUndefined(rec),
              );
            }
            if (json.configs) {
              for (const cfg of json.configs) {
                await setDoc(doc(db, "configs", cfg.id), removeUndefined(cfg));
              }
            }
            if (json.clinicConfig) {
              await setDoc(
                doc(db, "settings", "clinic"),
                removeUndefined(json.clinicConfig),
              );
            }

            alert(
              "Import finalizat cu succes! Toate datele au fost încărcate și sincronizate.",
            );
          } catch (error) {
            console.error("Import sync error:", error);
            alert(
              "Datele au fost încărcate local, dar sincronizarea cu baza de date a eșuat. Vă rugăm să verificați conexiunea.",
            );
          } finally {
            setLoading(false);
          }
        }
      } catch (err) {
        alert(
          "Eroare la importul datelor: " +
            (err instanceof Error ? err.message : "Fișier corupt"),
        );
      }
    };
    reader.readAsText(file);
    e.target.value = "";
  };

